package in.recallradar;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/production") class ProductionController{private final ProductionService service;private final TenantService tenants;ProductionController(ProductionService s,TenantService t){service=s;tenants=t;}private Membership m(Authentication a,String org){return tenants.membership(UUID.fromString(a.getName()),org);}@GetMapping("/products")List<ProductResponse> products(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.products(m(a,org));}@PostMapping("/products")@ResponseStatus(HttpStatus.CREATED)ProductResponse product(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody ProductRequest r){return service.product(m(a,org),r);}@GetMapping("/recipes")List<RecipeResponse> recipes(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.recipes(m(a,org));}@PostMapping("/recipes")@ResponseStatus(HttpStatus.CREATED)RecipeResponse recipe(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody RecipeRequest r){return service.createRecipe(m(a,org),r);}@GetMapping("/batches")List<ProductionResponse>batches(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org){return service.batches(m(a,org));}@PostMapping("/batches")@ResponseStatus(HttpStatus.CREATED)ProductionResponse produce(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody ProductionRequest r){return service.produce(m(a,org),r);}@PostMapping("/preview")ProductionPlanResponse preview(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody ProductionPlanRequest r){return service.preview(m(a,org),r);}@PostMapping("/suggested-batches")@ResponseStatus(HttpStatus.CREATED)ProductionResponse produceSuggested(Authentication a,@RequestHeader(value="X-Organization-Id",required=false)String org,@Valid @RequestBody ProductionPlanRequest r){return service.produceSuggested(m(a,org),r);}}
